head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > colSpan]<br/>Studio 에서 GridView 의 Column 병합 시 사용되는 속성입니다.",
    "validation" : [
        "직접 수정 및 설정하는 것을 금합니다.",
        "Column 병합 시, 병합한 Column 의 수가 표시됩니다.",
        "Studio 의 '병합' 기능을 사용하면 자동 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// target1 은 Studio 의 "병합" 기능으로 저장되는 형태(colSpan="N" rowSpan="")를 그대로 정적 선언한다.
//  - 직접 수정·설정 금지 속성이므로 con 옵션(임의 colSpan 값 설정)과 재생성 버튼은 두지 않는다.
//  - Header : 병합하지 않은 7개 Column (상품코드, 상품명, 모델명, 가격, 비고, 원산지, 제조사)
//  - gBody  : 상품코드(code) + 상품명(name, colSpan=2) + 가격(price) + 비고(memo, colSpan=3)
//    Studio 저장 형태대로 병합된 나머지 Column 은 삭제되고 첫 Column 의 width 는 합산 (120+100=220 / 150+90+90=330)



// validation 2 판정 출력 : 0번째 Row 에서 각 Body 셀의 colspan 과 실제로 걸쳐 표시되는 Header Column 범위 (code, price 는 병합하지 않은 대조 셀)
scwin.btn_checkColSpan_onclick = function () {
    let headThList = scwin.getHeaderCells();
    let tr = scwin.getBodyLine(0);
    let arrCol = [
        { id : "code", label : "상품코드" },
        { id : "name", label : "상품명" },
        { id : "price", label : "가격" },
        { id : "memo", label : "비고" }
    ];
    for (let i = 0; i < arrCol.length; i++) {
        let td = tr ? tr.querySelector("td[data-col_id='" + arrCol[i].id + "']") : null;
        if (!td) {
            wf_body_bottom.getObj("scwin").setReturnValue(arrCol[i].label + "(" + arrCol[i].id + ") : 셀 없음");
            continue;
        }
        let rect = td.getBoundingClientRect();
        let arrHead = [];
        for (let j = 0; j < headThList.length; j++) {
            let hRect = headThList[j].getBoundingClientRect();
            // 셀 영역이 Header Column 의 가로 중앙을 포함하면 해당 Column 에 걸쳐 표시된 것으로 판정
            let mid = hRect.left + hRect.width / 2;
            if (rect.left <= mid && mid <= rect.right) {
                arrHead.push(headThList[j].textContent);
            }
        }
        let strHead = (arrHead.length > 0) ? "Header '" + arrHead.join("', '") + "' 에 걸쳐 표시 (" + arrHead.length + "개 Column)" : "걸친 Column 없음";
        wf_body_bottom.getObj("scwin").setReturnValue(arrCol[i].label + "(" + arrCol[i].id + ") '" + td.textContent + "' : colspan " + (td.getAttribute("colspan") || "없음") + " -> " + strHead);
    }
}



// Header Line 의 Column 셀(th) 목록 (화면 왼쪽부터)
scwin.getHeaderCells = function () {
    let thList = document.querySelectorAll("#" + target1.id + "_head_table th[data-header_id]");
    return Array.prototype.filter.call(thList, function (th) { return th.offsetWidth > 0; });
}



// rowIndex 번째 레코드의 Body Line(tr)
scwin.getBodyLine = function (rowIndex) {
    let tbody = document.querySelector("#" + target1.id + "_body_tbody");
    let trList = tbody ? Array.prototype.filter.call(tbody.children, function (tr) { return tr.tagName === "TR" && tr.style.display !== "none" && tr.querySelector("td"); }) : [];
    return trList[rowIndex] || null;
}
